# Kuro - do not edit. The application code below is compressed; this loader unpacks and runs it.
# Readable source and the build tools live only in the owner's private pack.
$ErrorActionPreference='SilentlyContinue'
$Global:KuroHostPath=$PSCommandPath; if(-not $Global:KuroHostPath){$Global:KuroHostPath=$MyInvocation.MyCommand.Path}
$Global:KuroHostRoot=$PSScriptRoot
$Global:KuroHostArgs=$args
try{
  $kuroData=[Convert]::FromBase64String('')
  $kuroIn=New-Object IO.MemoryStream(,$kuroData)
  $kuroGz=New-Object IO.Compression.GZipStream($kuroIn,[IO.Compression.CompressionMode]::Decompress)
  $kuroRd=New-Object IO.StreamReader($kuroGz,[Text.Encoding]::UTF8)
  $Global:KuroInnerSource=$kuroRd.ReadToEnd(); $kuroRd.Close()
  Invoke-Expression $Global:KuroInnerSource
}catch{
  try{$kd=Join-Path $env:ProgramData 'Kuro'; if(-not(Test-Path $kd)){New-Item -ItemType Directory -Force -Path $kd|Out-Null}; [IO.File]::AppendAllText((Join-Path $kd 'error.txt'),('['+(Get-Date -Format s)+'] loader: '+$_.Exception.Message+[Environment]::NewLine))}catch{}
  try{Add-Type -AssemblyName System.Windows.Forms; [void][System.Windows.Forms.MessageBox]::Show('Kuro could not start. Please re-download the latest Kuro from the Discord. Details were saved to %ProgramData%\Kuro\error.txt.','Kuro')}catch{}
}
